using System.Linq;
using AiLabs.Rules.Config;
using AiLabs.Rules.Core;
using AiLabs.Rules.Sim;
using AiLabs.Rules.State;
using AiLabs.Rules.Systems;
using AiLabs.SimTests.Support;
using Xunit;

namespace AiLabs.SimTests;

/// <summary>Q736–Q805: batch 16 denouement — rivals/chips series closure (schema 31, WIP local).</summary>
public class HatchRivalsChipsDenouementLaterTests
{
    static ModelState R(Game g, int c) => new ModelState { Id = g.State.TakeId(), LineId = "mini", Capability = c, Status = ModelStatus.Released, Alignment = 500, Name = "D" };

    static void Acquire(Game g, LabState r)
    {
        if (!r.Models.Any(m => m.Capability >= 500)) r.Models.Add(R(g, 512));
        r.Cash = -16_400;
        r.WeeksInDebt = 1;
        Finance.Earn(g.Me, LedgerLine.CapitalIn, 90_000_000);
        g.Do(Command.AcquireLab(g.Id, r.Id));
    }

    [Fact] public void Q736_denouement_736() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 4200, 8)); LabState x = HatchFollowUpLaterTests.OpenAyeBuyer(g, 54_000_000); g.Do(Command.BuyListedChips(x.Id, g.Id, d.Id, HardwareBatch.Cloud, 1)); Acquire(g, x); Assert.Equal(GameState.CurrentSchema, g.State.Schema); }
    [Fact] public void Q737_denouement_737() { var g = Game.New(seed: 1361); var r = g.Rival("openaye"); r.Models.Add(R(g, 525)); r.Cash = -16_500; Finance.Earn(g.Me, LedgerLine.CapitalIn, 70_000_000); g.Do(Command.AcquireLab(g.Id, r.Id)); g.Refused(Command.RaiseFunding(r.Id, "angel"), CommandError.LabAbsorbed); }
    [Fact] public void Q738_denouement_738() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 4400, 6)); LabState x = HatchFollowUpLaterTests.OpenAyeBuyer(g, 46_000_000); long s = g.Me.Ledger.Lifetime.ChipSales; g.Do(Command.BuyListedChips(x.Id, g.Id, d.Id, HardwareBatch.Cloud, 1)); Assert.True(g.Me.Ledger.Lifetime.ChipSales > s); }
    [Fact] public void Q739_denouement_739() { var g = Game.New(seed: 1363); var r = g.Rival("openaye"); r.Models.Add(R(g, 538)); r.Cash = -17_400; Finance.Earn(g.Me, LedgerLine.CapitalIn, 80_000_000); g.Do(Command.AcquireLab(g.Id, r.Id)); Assert.Contains(g.State.Events, e => e.Kind == EventKind.LabAcquired); }
    [Fact] public void Q740_denouement_740() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 4000, 8)); LabState x = HatchFollowUpLaterTests.OpenAyeBuyer(g, 52_000_000); g.Do(Command.BuyListedChips(x.Id, g.Id, d.Id, HardwareBatch.Cloud, 1)); Acquire(g, x); SaveSchemaPretend.AssertRoundTrip(g.Sim); }
